export function evaluate({ inputs, time }) {
  const u = inputs.launchSpeed;
  const g = inputs.gravity;
  const m = inputs.mass;

  const tTop = u / g;
  const yTop = (u * u) / (2 * g);

  const t = Math.max(0, Math.min(time, 2 * tTop));
  const y = u * t - 0.5 * g * t * t;
  const v = u - g * t;
  const a = -g;
  const Fg = m * g;

  let state = "Ready to toss";
  if (t > 0 && t < tTop - 0.05) state = "Rising";
  else if (t >= tTop - 0.05 && t <= tTop + 0.05) state = "At the top";
  else if (t > tTop + 0.05 && y > 0) state = "Falling";
  else if (y <= 0 && t > 0) state = "Back at launch height";

  const objects = [];

  // Panels
  objects.push(...sdk.panel({ x: 20, y: 35, w: 290, h: 360, title: "The Motion", state }));
  objects.push(...sdk.panel({ x: 330, y: 35, w: 290, h: 360, title: "Velocity over time", state: `t = ${sdk.format(t, 2)} s` }));

  // Left Scene: Axis & Ball
  objects.push(sdk.axis("axis.height", { x: 50, y: 360, length: 280, orientation: "y", min: 0, max: 2.2, ticks: [0, 0.5, 1.0, 1.5, 2.0], label: "Height", unit: "m" }));

  const ballY = 360 - (y / 2.2) * 280;
  objects.push(sdk.circle("ball.toss", 165, ballY, 24, { role: "output" }));

  // Vectors on ball
  objects.push(...sdk.vector("vec.v", { x: 185, y: ballY }, { value: v, direction: "up" }, { scale: 12, label: "v", role: "output" }));
  objects.push(...sdk.vector("vec.a", { x: 145, y: ballY }, { value: a, direction: "up" }, { scale: 12, label: "a", role: "prediction" }));

  // Callout beside ball
  objects.push(...sdk.callout(200, ballY - 25, [
    `v: ${sdk.format(v, 2)} m/s`,
    `a: ${sdk.format(a, 1)} m/s^2`,
    `Fg: ${sdk.format(Fg, 1)} N`
  ], { role: "output" }));

  // Right Scene: Plot vt
  const points = [];
  const steps = 20;
  for (let i = 0; i <= steps; i++) {
    const st = (i / steps) * (2 * tTop);
    const sv = u - g * st;
    points.push([st, sv]);
  }

  const currentPoints = [];
  const currSteps = Math.max(2, Math.floor((t / (2 * tTop)) * steps));
  for (let i = 0; i <= currSteps; i++) {
    const st = (i / currSteps) * t;
    const sv = u - g * st;
    currentPoints.push([st, sv]);
  }

  objects.push(sdk.plot("plot.vt", {
    x: 350,
    y: 75,
    w: 250,
    h: 220,
    axes: {
      x: { label: "Time", min: 0, max: Math.max(1.8, 2 * tTop), unit: "s" },
      y: { label: "Velocity", min: -5.5, max: 5.5, unit: "m/s" }
    },
    series: [
      { label: "v(t)", kind: "line", points }
    ],
    marker: { x: t, y: v, label: "t" }
  }));

  objects.push(sdk.text("plot.vt.note", 360, 320, `Slope a = -g = ${sdk.format(-g, 1)} m/s^2`, { role: "neutral" }));

  return {
    frame: {
      width: 640,
      height: 420,
      objects,
      readouts: [
        { id: "velocity", value: Number(v.toFixed(2)) },
        { id: "acceleration", value: Number(a.toFixed(2)) },
        { id: "force", value: Number(Fg.toFixed(2)) },
        { id: "motionState", value: state }
      ]
    },
    quantities: {
      launchSpeed: u,
      gravity: g,
      mass: m,
      apexTime: tTop,
      apexHeight: yTop,
      height: y,
      velocity: v,
      acceleration: a,
      force: Fg
    }
  };
}
